insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, thumbnail_url, display_url, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('조형예술과 음악 (Képzőművészet és zene)', '니콜라 쉐페르 (Nicolas Schöffer)', '부다페스트 뮈차르노크(Műcsarnok)의 쉐페르 전시에서 찍힌 사진이다. 시계 문자판 모양 원반과 화살표 형태의 금속 구조물이 ''시간(TEMPS)''과 ''아이디어(IDÉES)'' 글자와 함께 배치돼 있다.', 2016, '금속, 목재 (사진 기준 추정)', NULL, ARRAY['키네틱아트','기계조형','시간','니콜라쉐페르']::text[], 'https://images.kctikinec.cloud/cards/552.webp?v=6c1a7502ad', 'https://images.kctikinec.cloud/display/552.webp?v=dbcdbe4d0e', 'https://images.kctikinec.cloud/works/552.jpg', 'https://images.kctikinec.cloud/texts/552.txt', NULL, 0.315, 'CC BY-SA 4.0', 'Ittisottis / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:K%C3%A9pz%C5%91m%C5%B1v%C3%A9szet_%C3%A9s_zene.jpg')
